// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);
        require(tos.length > 0, "empty");

        Recorder rec = new Recorder();
        bool ok = c.transfer(from, address(rec), tos, v);
        assertTrue(ok && rec.count() == tos.length && rec.lastFrom() == from && rec.lastTo() == tos[tos.length - 1] && rec.lastAmount() == v);
    }
}

contract Recorder {
    uint256 public count;
    address public lastFrom;
    address public lastTo;
    uint256 public lastAmount;

    function transferFrom(address f, address t, uint256 a) external returns (bool) {
        count++;
        lastFrom = f;
        lastTo = t;
        lastAmount = a;
        return true;
    }
}
